                if '=' in key:
                    key, value = key.split('=', 1)
                    self.arguments[key] = self._convert_type(key, value)
                elif i + 1 < len(parts) and not parts[i + 1].startswith('-'):
                    self.arguments[key] = self._convert_type(key, parts[i + 1])
                    i += 1
                else:
