class ExpressionCalculator:
    """
    This is a class in Python that can perform calculations with basic arithmetic operations, including addition, subtraction, multiplication, division, and modulo.
    """

    def __init__(self):
        """
        Initialize the expression calculator
        """
        self.postfix_stack = deque()
        # Priority mapping: '(':0, '+':1, '-':1, '*':2, '/':2, '%':2, ')':3
        # Based on the provided list: [0, 3, 2, 1, -1, 1, 0, 2]
        self.ops = {'(': 0, '+': 1, '-': 1, '*': 2, '/': 2, '%': 2, ')': 3}

    def calculate(self, expression):
        """
        Calculate the result of the given infix expression
        """
        self.prepare(self.transform(expression))
        stack = []
        while self.postfix_stack:
            token = self.postfix_stack.popleft()
            if not self.is_operator(token):
                stack.append(float(token))
            else:
                val2 = stack.pop()
                val1 = stack.pop()
                stack.append(float(self._calculate(val1, val2, token)))
        return stack[0]

    def prepare(self, expression):
        """
        Prepare the infix expression for conversion to postfix notation using Shunting-yard algorithm
        """
        self.postfix_stack = deque()
        operator_stack = []
        # Tokenize numbers and operators
        tokens = re.findall(r'\d+\.?\d*|[+\-*/%()]', expression)

        for token in tokens:
            if token.replace('.', '', 1).isdigit():
                self.postfix_stack.append(token)
            elif token == '(':
                operator_stack.append(token)
            elif token == ')':
                while operator_stack and operator_stack[-1] != '(':
                    self.postfix_stack.append(operator_stack.pop())
                operator_stack.pop()
            else:
                while operator_stack and self.compare(token, operator_stack[-1]):
                    self.postfix_stack.append(operator_stack.pop())
                operator_stack.append(token)

        while operator_stack:
            self.postfix_stack.append(operator_stack.pop())

    @staticmethod
    def is_operator(c):
        """
        Check if a character is an operator in {'+', '-', '*', '/', '(', ')', '%'}
        """
        return c in {'+', '-', '*', '/', '(', ')', '%'}

    def compare(self, cur, peek):
        """
        Compare the precedence of two operators
        """
        if peek == '(':
            return False
        return self.ops[cur] <= self.ops[peek]

    @staticmethod
    def _calculate(first_value, second_value, current_op):
        """
        Perform the mathematical calculation based on the given operands and operator
        """
        if current_op == '+': return first_value + second_value
        if current_op == '-': return first_value - second_value
        if current_op == '*': return first_value * second_value
        if current_op == '/': return first_value / second_value
        if current_op == '%': return first_value % second_value
        return 0.0

    @staticmethod
    def transform(expression):
        """
        Transform the infix expression to a format suitable for conversion (remove spaces)
        """
        return expression.replace(" ", "")

class FitnessTracker:
    """
    This is a class as fitness tracker that implements to calculate BMI (Body Mass Index) and calorie intake based on the user's height, weight, age, and sex.
    """

    def __init__(self, height, weight, age, sex) -> None:
        """
        Initialize the class with height, weight, age, and sex, and calculate the BMI standard based on sex, and male is 20-25, female is 19-24.
        """
        self.height = height
        self.weight = weight
        self.age = age
        self.sex = sex
        self.BMI_std = {
            "male": [20, 25],
            "female": [19, 24]
        }

    def get_BMI(self):
        """
        Calculate the BMI based on the height and weight.
        :return: BMI,which is the weight divide by the square of height, float.
        """
        return self.weight / (self.height ** 2)

    def condition_judge(self):
        """
        Judge the condition of the user based on the BMI standard.
        :return: 1 if the user is too fat, -1 if the user is too thin, 0 if the user is normal, int.
        """
        bmi = self.get_BMI()
        std = self.BMI_std[self.sex]
        if bmi > std[1]:
            return 1
        elif bmi < std[0]:
            return -1
        else:
            return 0

    def calculate_calorie_intake(self):
        """
        Calculate the calorie intake based on the user's condition and BMR (Basal Metabolic Rate),BMR is calculated based on the user's height, weight, age, and sex,male is 10 * self.weight + 6.25 * (self.height * 100) - 5 * self.age + 5,female is 10 * self.weight + 6.25 * (self.height * 100) - 5 * self.age - 161, and the calorie intake is calculated based on the BMR and the user's condition,if the user is too fat, the calorie intake is BMR * 1.2, if the user is too thin, the calorie intake is BMR * 1.6, if the user is normal, the calorie intake is BMR * 1.4.
        :return: calorie intake, float.
        """
        # Note: BMR formulas typically use height in cm
        h_cm = self.height * 100
        if self.sex == "male":
            bmr = 10 * self.weight + 6.25 * h_cm - 5 * self.age + 5
        else:
            bmr = 10 * self.weight + 6.25 * h_cm - 5 * self.age - 161

        condition = self.condition_judge()
        if condition == 1:
            return bmr * 1.2
        elif condition == -1:
            return bmr * 1.6
        else:
            return bmr * 1.4

class Hotel:
    """
    This is a class as hotel management system, managing the booking, check-in, check-out, and availability of rooms in a hotel with different room types.
    """

    def __init__(self, name, rooms):
        """
        Initialize the three fields in Hotel System.
        """
        self.name = name
        self.available_rooms = rooms
        self.booked_rooms = {}

    def book_room(self, room_type, room_number, name):
        """
        Check if there are any rooms of the specified type available.
        """
        if room_type not in self.available_rooms or self.available_rooms[room_type] == 0:
            return False

        if room_number <= self.available_rooms[room_type]:
            self.available_rooms[room_type] -= room_number
            if room_type not in self.booked_rooms:
                self.booked_rooms[room_type] = {}
            self.booked_rooms[room_type][name] = self.booked_rooms[room_type].get(name, 0) + room_number
            return 'Success!'
        else:
            return self.available_rooms[room_type]

    def check_in(self, room_type, room_number, name):
        """
        Check if the room of the specified type and number is booked by the person named name.
        """
        if room_type not in self.booked_rooms or name not in self.booked_rooms[room_type]:
            return False

        if room_number > self.booked_rooms[room_type][name]:
            return False

        self.booked_rooms[room_type][name] -= room_number
        if self.booked_rooms[room_type][name] == 0:
            del self.booked_rooms[room_type][name]

        # If the dictionary for this room type is empty, clean it up
        if not self.booked_rooms[room_type]:
            del self.booked_rooms[room_type]

    def check_out(self, room_type, room_number):
        """
        Check out rooms, add number for specific type in available_rooms.
        """
        if room_type in self.available_rooms:
            self.available_rooms[room_type] += room_number
        else:
            self.available_rooms[room_type] = room_number

    def get_available_rooms(self, room_type):
        """
        Get the number of specific type of available rooms.
        """
        return self.available_rooms.get(room_type, 0)

class IPAddress:
    """
    This is a class to process IP Address, including validating, getting the octets and obtaining the binary representation of a valid IP address.
    """

    def __init__(self, ip_address):
        """
        Initialize the IP address to the specified address
        :param ip_address:string
        """
        self.ip_address = ip_address

    def is_valid(self):
        """
        Judge whether the IP address is valid, that is, whether the IP address is composed of four Decimal digits separated by '.'. Each digit is greater than or equal to 0 and less than or equal to 255
        :return: bool
        """
        octets = self.ip_address.split('.')
        if len(octets) != 4:
            return False
        for octet in octets:
            if not octet.isdigit():
                return False
            if not (0 <= int(octet) <= 255):
                return False
            # Check for leading zeros (e.g., "01" is usually considered invalid in strict IP parsing)
            if len(octet) > 1 and octet[0] == '0':
                return False
        return True

    def get_octets(self):
        """
        If the IP address is valid, the list of four decimal numbers separated by "." constituting the IP address is returned; otherwise, an empty list is returned
        :return: list
        """
        if self.is_valid():
            return self.ip_address.split('.')
        return []

    def get_binary(self):
        """
        If the IP address is valid, return the binary form of the IP address; otherwise, return ''
        :return: string
        """
        if self.is_valid():
            octets = self.get_octets()
            binary_octets = [format(int(octet), '08b') for octet in octets]
            return ".".join(binary_octets)
        return ""

