    @staticmethod
    def get_hostname(ip_address):
        """
        Get the hostname associated with the given IP address.
        :param ip_address:string, the IP address to get the hostname for
        :return: string, the hostname associated with the IP address
        """
        try:
            return socket.gethostbyaddr(ip_address)[0]
        except (socket.herror, socket.gaierror):
            return None

import random

class MahjongConnect:
    """
    MahjongConnect is a class representing a game board for Mahjong Connect with features like creating the board, checking valid moves, finding paths, removing icons, and checking if the game is over.
    """

    def __init__(self, BOARD_SIZE, ICONS):
        self.BOARD_SIZE = BOARD_SIZE
        self.ICONS = ICONS
        self.board = self.create_board()

    def create_board(self):
        rows, cols = self.BOARD_SIZE
        total_cells = rows * cols
        # Fill board with pairs of icons
        flat_list = []
        for _ in range(total_cells // len(self.ICONS)):
            flat_list.extend(self.ICONS)
        while len(flat_list) < total_cells:
            flat_list.append(random.choice(self.ICONS))

        random.shuffle(flat_list)
        return [flat_list[i * cols:(i + 1) * cols] for i in range(rows)]

    def is_valid_move(self, pos1, pos2):
        r1, c1 = pos1
        r2, c2 = pos2
        rows, cols = self.BOARD_SIZE

        # Check bounds
        if not (0 <= r1 < rows and 0 <= c1 < cols and 0 <= r2 < rows and 0 <= c2 < cols):
            return False
        # Check same position
        if pos1 == pos2:
            return False
        # Check same icon and not empty
        if self.board[r1][c1] == ' ' or self.board[r1][c1] != self.board[r2][c2]:
            return False

        return self.has_path(pos1, pos2)

    def has_path(self, pos1, pos2):
        # Simple BFS to check if a path exists (ignoring the 2-turn constraint for basic connectivity)
        # In standard Mahjong Connect, this would check for max 2 turns.
        # Here we implement a standard pathfinding check.
        queue = [pos1]
        visited = {pos1}
        while queue:
            curr_r, curr_c = queue.pop(0)
            if (curr_r, curr_c) == pos2:
                return True
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < self.BOARD_SIZE[0] and 0 <= nc < self.BOARD_SIZE[1]:
                    if (nr, nc) not in visited and (self.board[nr][nc] == ' ' or (nr, nc) == pos2):
                        visited.add((nr, nc))
                        queue.append((nr, nc))
        return False

    def remove_icons(self, pos1, pos2):
        r1, c1 = pos1
        r2, c2 = pos2
        self.board[r1][c1] = ' '
        self.board[r2][c2] = ' '

    def is_game_over(self):
        for row in self.board:
            for cell in row:
                if cell != ' ':
                    return False
        return True

import numpy as np


class MetricsCalculator2:
    """
    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP) based on input data, where MRR measures the ranking quality and MAP measures the average precision.
    """

    def __init__(self):
        pass

    @staticmethod
    def mrr(data):
        """
        compute the MRR of the input data. MRR is a widely used evaluation index. It is the mean of reciprocal rank.
        """
        if isinstance(data, tuple):
            data = [data]

        rr_list = []
        for items, _ in data:
            try:
                # Find the index of the first '1' (1-based)
                rank = items.index(1) + 1
                rr_list.append(1.0 / rank)
            except ValueError:
                # If no '1' is found, reciprocal rank is 0
                rr_list.append(0.0)

        return np.mean(rr_list), rr_list

    @staticmethod
    def map(data):
        """
        compute the MAP of the input data. MAP is a widely used evaluation index. It is the mean of AP (average precision).
        """
        if isinstance(data, tuple):
            data = [data]

        ap_list = []
        for items, ground_truth_num in data:
            if ground_truth_num == 0:
                ap_list.append(0.0)
                continue

            precision_at_k = []
            correct_found = 0
            for i, val in enumerate(items):
                if val == 1:
                    correct_found += 1
                    precision_at_k.append(correct_found / (i + 1))

            if not precision_at_k:
                ap_list.append(0.0)
            else:
                # AP = sum(precision at each relevant item) / total ground truth
                ap_list.append(sum(precision_at_k) / ground_truth_num)

        return np.mean(ap_list), ap_list

from datetime import datetime
import numpy as np

class MovieBookingSystem:
    """
    this is a class as movie booking system, which allows to add movies, book tickets and check the available movies within a given time range. 
    """

    def __init__(self):
        self.movies = []

    def add_movie(self, name, price, start_time, end_time, n):
        """
        Add a new movie into self.movies
        """
        start = datetime.strptime(start_time, '%H:%M')
        end = datetime.strptime(end_time, '%H:%M')
        movie = {
            'name': name,
            'price': price,
            'start_time': start,
            'end_time': end,
            'seats': np.zeros((n, n))
        }
        self.movies.append(movie)

    def book_ticket(self, name, seats_to_book):
        """
        Book tickets for a movie. Change the seats value in self.movies if book successfully.
        """
        target_movie = None
        for movie in self.movies:
            if movie['name'] == name:
                target_movie = movie
                break

        if target_movie is None:
            return "Movie not found."

        # Check if all requested seats are available (0)
        for r, c in seats_to_book:
            if target_movie['seats'][r, c] != 0:
                return "Booking failed."

        # Book the seats
        for r, c in seats_to_book:
            target_movie['seats'][r, c] = 1

        return "Booking success."

    def available_movies(self, start_time, end_time):
        """
        Get a list of available movies within the specified time range
        """
        start_range = datetime.strptime(start_time, '%H:%M')
        end_range = datetime.strptime(end_time, '%H:%M')

        available = []
        for movie in self.movies:
            if movie['start_time'] >= start_range and movie['end_time'] <= end_range:
                available.append(movie['name'])
        return available

class NumberWordFormatter:
    """
    This is a class that provides to convert numbers into their corresponding English word representation, including handling the conversion of both the integer and decimal parts, and incorporating appropriate connectors and units.
    """

    def __init__(self):
        """
        Initialize NumberWordFormatter object.
        """
        self.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        self.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        self.NUMBER_TEN = ["", "TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        self.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]

    def format(self, x):
        """
        Converts a number into words format
        """
        return self.format_string(str(x))

    def format_string(self, x):
        """
        Converts a string representation of a number into words format
        """
        if '.' in x:
            integer_part, decimal_part = x.split('.')
        else:
            integer_part, decimal_part = x, ""

        parts = []
        chunks = []
        for i in range(len(integer_part), 0, -3):
            chunks.append(integer_part[max(0, i - 3):i])

        for i, chunk in enumerate(chunks):
            word = self.trans_three(chunk.zfill(3))
            if word:
                suffix = self.parse_more(i)
                parts.append(f"{word} {suffix}".strip())

        result = " AND ".join(reversed(parts))
        return f"{result} ONLY"

    def trans_two(self, s):
        """
        Converts a two-digit number into words format
        """
        n = int(s)
        if n < 10:
            return self.NUMBER[n]
        elif n < 20:
            return self.NUMBER_TEEN[n - 10]
        else:
            tens = self.NUMBER_TEN[n // 10]
            ones = self.NUMBER[n % 10]
            return f"{tens} {ones}".strip()

    def trans_three(self, s):
        """
        Converts a three-digit number into words format
        """
        n = int(s)
        if n == 0:
            return ""

        hundreds = self.NUMBER[n // 100]
        rest = self.trans_two(s[1:])

        if hundreds and rest:
            return f"{hundreds} HUNDRED AND {rest}"
        elif hundreds:
            return f"{hundreds} HUNDRED"
        else:
            return rest

    def parse_more(self, i):
        """
        Parses the thousand/million/billion suffix based on the index
        """
        if i < len(self.NUMBER_MORE):
            return self.NUMBER_MORE[i]
        return ""

import re

class NumericEntityUnescaper:
    """
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    """

    def __init__(self):
        pass

    def replace(self, string):
        """
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'
        """
        def replace_match(match):
            entity = match.group(1)
            try:
                if entity.lower().startswith('x'):
                    code = int(entity[1:], 16)
                else:
                    code = int(entity)
                return chr(code)
            except (ValueError, OverflowError):
                return match.group(0)

        return re.sub(r'&#([xX][0-9a-fA-F]+|[0-9]+);', replace_match, string)

    @staticmethod
    def is_hex_char(char):
        """
        Determines whether a given character is a hexadecimal digit.
        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        >>> NumericEntityUnescaper.is_hex_char('a')
        True
        """
        return char.lower() in '0123456789abcdef'

class Order:
    """
    The class manages restaurant orders by allowing the addition of dishes, calculation of the total cost, and checkout.
    """

    def __init__(self):
        """
        Initialize the order management system
        self.menu stores the dishes of resturant inventory
        menu = [{"dish": dish name, "price": price, "count": count}, ...]
        self.selected_dishes stores the dished selected by customer
        selected_dish = {"dish": dish name, "count": count, price: price}
        self.sales stores the sales of each dish
        sales = {dish name: sales}
        """
        self.menu = []
        self.selected_dishes = []
        self.sales = {}

    def add_dish(self, dish):
        """
        Check the self.menu and add into self.selected_dish if the dish count is valid.
        And if the dish has successfully been added, change the count in self.menu.
        :param dish: dict, the information of dish. dish = {"dish": dish name, "count": count, price: price}
        :return: True if successfully added, or False otherwise.
        """
        for item in self.menu:
            if item["dish"] == dish["dish"]:
                if item["count"] >= dish["count"]:
                    item["count"] -= dish["count"]
                    self.selected_dishes.append(dish)
                    return True
                else:
                    return False
        return False

    def calculate_total(self):
        """
        Calculate the total price of dishes that have been ordered. Multiply the count, price and sales.
        :return total: float, the final total price.
        """
        total = 0.0
        for item in self.selected_dishes:
            dish_name = item["dish"]
            price = item["price"]
            count = item["count"]
            sale_multiplier = self.sales.get(dish_name, 1.0)
            total += price * count * sale_multiplier
        return float(total)

    def checkout(self):
        """
        Check out the dished ordered. IF the self.selected_dishes is not empty, invoke the calculate_total
        method to check out.
        :return Flase if the self.selected_dishes is empty, or total(return value of calculate_total) otherwise.
        """
        if not self.selected_dishes:
            return False
        return self.calculate_total()
